{"hypothesis":"Changing the comb pitch coherently at low-mass seams, rather than polishing individual coordinates, can escape the incumbent topology and gain at least 1e-5.","rationale":"An integer shear moves successive packets by successive integer offsets while retaining their original samples and avoiding interpolation. The search infers several plausible packet periods from the warm start, tests both pitch contractions and expansions, and retains a candidate only after scoring it with the frozen verifier's formula.","source":"import time
import numpy as np
from scipy.signal import oaconvolve

PARAMS = {
    'time_fraction': (0.68, 0.5, 0.72),
    'period_count': (12, 3, 24),
    'max_step': (3, 1, 8),
}


def construct(params: dict, seed: int, budget_s: float, init=None):
    started = time.monotonic()
    deadline = started + float(params['time_fraction']) * budget_s
    rng = np.random.default_rng(seed)
    if init is None:
        return {'values': [1.0]}

    if 'values' in init:
        original = init['values']
    else:
        a = init['ring']
        k = int(init.get('cut', 0))
        mode = int(init.get('reflection', 0))
        if mode == 1:
            original = a[:k][::-1] + a[k:]
        elif mode == 2:
            original = a[:k] + a[k:][::-1]
        else:
            original = a[k:] + a[:k] if k else a
    f = np.maximum(np.asarray(original, dtype=np.float64), 0.0)

    def score(a):
        c = oaconvolve(a, a, mode='full')
        # Deliberately use the verifier's operations, including its grid.
        dx = np.diff(np.linspace(-0.5, 0.5, len(c) + 2))
        y = np.concatenate(([0.0], c, [0.0]))
        q = float(np.sum((dx / 3.0) *
                         (y[:-1] ** 2 + y[:-1] * y[1:] + y[1:] ** 2)))
        return q / ((np.sum(np.abs(c)) / (len(c) + 1)) *
                    np.max(np.abs(c)))

    best_score = score(f)
    best = None
    # Removing external zero padding does not alter the exact algebraic score.
    nz = np.flatnonzero(f > 0)
    if len(nz) == 0:
        return init
    base = f[nz[0]:nz[-1] + 1].copy()
    n = len(base)
    if n < 8 or time.monotonic() >= deadline:
        return init

    def consider(a):
        nonlocal best, best_score
        if time.monotonic() >= deadline - 0.7:
            return
        if len(a) == 0 or len(a) > 2000000:
            return
        s = score(a)
        if np.isfinite(s) and s > best_score:
            best_score = s
            best = a.copy()

    # Different thresholds reveal both the narrow teeth and their envelopes.
    votes = {}
    run_sets = []
    peak = float(np.max(base))
    for threshold in (1e-10, 1e-7, 1e-5, 1e-3, 0.01):
        if time.monotonic() >= deadline - 1.0:
            break
        mask = base > peak * threshold
        edges = np.diff(np.r_[False, mask, False].astype(np.int8))
        starts = np.flatnonzero(edges == 1)
        ends = np.flatnonzero(edges == -1)
        if len(starts) < 3:
            continue
        run_sets.append((starts, ends))
        d = np.diff(starts)
        d = d[(d >= 3) & (d <= max(4, n // 3))]
        if len(d) == 0:
            continue
        vals, counts = np.unique(d, return_counts=True)
        order = np.argsort(counts)[-8:]
        for j in order:
            p = int(vals[j])
            votes[p] = votes.get(p, 0.0) + float(counts[j]) / len(d)
        p = int(np.median(d))
        votes[p] = votes.get(p, 0.0) + 0.3

    periods = sorted(votes, key=lambda p: -votes[p])
    # Also probe subharmonics: one detected envelope can contain several teeth.
    extra = []
    for p in periods[:5]:
        if time.monotonic() >= deadline - 1.0:
            break
        for divisor in (2, 3, 4):
            q = int(round(p / divisor))
            if q >= 4 and q not in votes and q not in extra:
                extra.append(q)
    periods = (periods[:int(params['period_count'])] + extra[:5])
    if not periods:
        periods = [max(4, n // k) for k in (64, 128, 256, 512)]

    indices = np.arange(n, dtype=np.int64)
    prepared = []
    for p in periods:
        if time.monotonic() >= deadline - 1.0:
            break
        if p < 3 or p > n // 2:
            continue
        residues = indices % p
        mass = np.bincount(residues, weights=base, minlength=p)
        # Cuts inside an empty band preserve entire packets, not just peaks.
        seam_cost = mass + np.roll(mass, 1) + np.roll(mass, -1)
        seam = int(np.argmin(seam_cost))
        phase = (p - seam) % p
        labels = (indices + phase) // p
        labels -= labels[0]
        prepared.append((p, labels, float(seam_cost[seam])))

    # Breadth first: every inferred comb gets its smallest topology change.
    for step in range(1, int(params['max_step']) + 1):
        if time.monotonic() >= deadline - 1.0:
            break
        for p, labels, cost in prepared:
            if time.monotonic() >= deadline - 1.0:
                break
            for sign in (-1, 1):
                if time.monotonic() >= deadline - 1.0:
                    break
                delta = sign * step
                if p + delta < 2:
                    continue
                positions = indices + delta * labels
                lo = int(positions.min())
                hi = int(positions.max())
                if hi - lo + 1 > 2000000:
                    continue
                a = np.bincount(positions - lo, weights=base,
                                minlength=hi - lo + 1)
                consider(a)

    # A distinct coherent move uses packet ordinal rather than spatial period.
    # This changes a nonuniform comb without independently scrambling its teeth.
    if run_sets:
        starts, ends = max(run_sets, key=lambda z: len(z[0]))
        if 3 <= len(starts) <= 100000:
            cuts = (ends[:-1] + starts[1:]) // 2
            packet = np.searchsorted(cuts, indices, side='right')
            for delta in (-2, -1, 1, 2):
                if time.monotonic() >= deadline - 1.0:
                    break
                positions = indices + delta * packet
                lo = int(positions.min())
                hi = int(positions.max())
                if hi - lo + 1 <= 2000000:
                    a = np.bincount(positions - lo, weights=base,
                                    minlength=hi - lo + 1)
                    consider(a)

    # Try a second pitch change on an actually improved structure only.
    if best is not None and time.monotonic() < deadline - 1.5:
        incumbent = best.copy()
        m = len(incumbent)
        ii = np.arange(m, dtype=np.int64)
        for p, _, _ in prepared[:4]:
            if time.monotonic() >= deadline - 1.0:
                break
            mass = np.bincount(ii % p, weights=incumbent, minlength=p)
            seam = int(np.argmin(mass + np.roll(mass, 1) + np.roll(mass, -1)))
            lab = (ii + (p - seam) % p) // p
            lab -= lab[0]
            for delta in (-1, 1):
                if time.monotonic() >= deadline - 1.0:
                    break
                pos = ii + delta * lab
                lo, hi = int(pos.min()), int(pos.max())
                if hi - lo + 1 <= 2000000:
                    consider(np.bincount(pos - lo, weights=incumbent,
                                         minlength=hi - lo + 1))

    if best is None:
        return init
    return {'values': best.tolist()}
"}
